use std::fs::File;
use std::io::{self, Read};

// 定义自定义错误枚举，封装不同错误源
#[derive(Debug)]
enum AppError {
    IoError(io::Error),   // I/O 错误
    ParseError,           // 解析错误
}

// 实现 From trait，允许从 io::Error 自动转换为 AppError
impl From<io::Error> for AppError {
    fn from(err: io::Error) -> Self {
        AppError::IoError(err)
    }
}

// 函数：从文件读取内容并解析为数字，使用 Result 返回
fn read_number_from_file(path: &str) -> Result<i32, AppError> {
    let mut file = File::open(path)?;  // 使用 ? 操作符传播错误
    let mut content = String::new();
    file.read_to_string(&mut content)?;  // 同样使用 ? 操作符

    // 尝试解析内容为整数，失败时返回 ParseError
    content.trim().parse().map_err(|_| AppError::ParseError)
}

fn main() {
    match read_number_from_file("data.txt") {
        Ok(number) => println!("成功读取数字: {}", number),
        Err(e) => eprintln!("错误发生: {:?}", e),  // 使用 eprintln 输出错误
    }
}

